import{_ as t,o,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const R=JSON.parse('{"title":"2019-10-31 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-10-31 :: Ceph Performance Meeting","date":"2019-10-31T00:00:00.000Z","updated":"2019-11-04T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","RocksDB","BlueStore"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-31_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-10-31_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-10-31_-_-_Ceph_Performance_Meeting.md"};function i(n,e,a,p,g,_){return o(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： David、Casey、Eric、Adam、Prasad、Matt等</p><p><strong>会议主题</strong>： Ceph分布式存储项目性能进展及讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、项目进展</strong></p><ol><li><p><strong>PRs状态</strong>：</p><ul><li>新的Orbitty缓存复制日志PR已提交，待审查。</li><li>Rosanell提交了多个关于Numa亲和力更新和增强的PR，包括OSD和GW。</li><li>Eric的PR涉及桶索引的动态重启，已合并。</li><li>Adams的PR修复了某些日志行为，以支持Roxie的PR，已合并。</li><li>其他PRs状态更新，包括对缓存、JW桶分片数量、蓝存储性能优化等。</li></ul></li><li><p><strong>讨论话题</strong>：</p><ul><li><strong>RocksDB分片</strong>： Adam分享了他在RocksDB分片方面的测试结果，发现分片对延迟影响不大，但写放大和压缩时间有所改善。讨论了分片可能导致延迟的原因，以及如何提高性能。</li><li><strong>BlueStore性能优化</strong>： 讨论了BlueStore性能优化PR，包括同步收集列表和压缩率等。</li><li><strong>Rgw桶分片</strong>： 讨论了提高Rgw桶分片数量的PR，以及如何平衡分片数量和性能之间的关系。</li></ul></li></ol><p><strong>二、决定事项</strong></p><ol><li>对RocksDB分片进行进一步测试，以验证性能改进和延迟影响。</li><li>对BlueStore性能优化PR进行审查和合并。</li><li>对Rgw桶分片数量进行测试，以确定最佳分片数量。</li></ol><p><strong>三、后续行动计划</strong></p><ol><li>Adam将继续测试RocksDB分片，并与团队分享测试结果。</li><li>Eric将审查BlueStore性能优化PR，并与团队讨论合并事宜。</li><li>Prasad将进行Rgw桶分片测试，并与团队讨论结果。</li></ol><p><strong>四、其他事项</strong></p><ol><li>讨论了RocksDB锁定的潜在问题，以及如何解决。</li><li>讨论了Rgw桶创建和删除的性能问题。</li></ol><p><strong>五、会议总结</strong></p><p>本次会议讨论了Ceph分布式存储项目的多个关键议题，包括性能优化和潜在问题，并制定了后续行动计划。团队将继续努力优化Ceph性能，并解决潜在问题。</p><p><strong>改进点</strong>：</p><ul><li>修正了原总结中“PRs状态”部分的具体信息，确保涵盖所有提及的PR。</li><li>在“讨论话题”部分，更详细地描述了RocksDB分片和BlueStore性能优化讨论的细节。</li><li>在“后续行动计划”部分，增加了对RocksDB锁定问题和Rgw桶性能问题的讨论。</li><li>确保保留所有计算机科学/ceph相关领域的英文原文关键词。</li></ul>',18)])])}const d=t(s,[["render",i]]);export{R as __pageData,d as default};
